using System;
using System.Linq;
using UnityEngine;
namespace BWVR {
[Serializable] public sealed class BuildBowlProject {
 public GatewayPhase phase;public int attempts,completed,placementCursor,shots,returns,lastReturnedShot,creatureShots,creatureHits,lastCreatureTurn;public float began,finished;public long playerPieces,creaturePieces;public bool playerHit,creatureHit;
 public bool Shared=>playerPieces!=0&&creaturePieces!=0;const long Mask=(1L<<ConstructionSite.YardPieces)-1;
 public bool Begin(int nextReceipt,float now){if(phase==GatewayPhase.Active||attempts>=1000000||nextReceipt<1||!HybridState.Number(now,0,100000000))return false;phase=GatewayPhase.Active;attempts++;placementCursor=nextReceipt-1;began=now;finished=0;shots=returns=lastReturnedShot=creatureShots=creatureHits=lastCreatureTurn=0;playerPieces=creaturePieces=0;playerHit=creatureHit=false;return true;}
 public bool RecordCreatureTurn(int shot,bool hit){if(phase!=GatewayPhase.Active||shot!=shots||shot!=lastReturnedShot||shot<=lastCreatureTurn)return false;lastCreatureTurn=shot;creatureShots++;if(hit)creatureHits++;return true;} public bool RecordReturn(int shot){if((phase!=GatewayPhase.Active&&phase!=GatewayPhase.Complete)||shot!=shots||shot<=lastReturnedShot)return false;lastReturnedShot=shot;returns++;return true;} public bool End(){if(phase!=GatewayPhase.Active)return false;phase=GatewayPhase.Ended;return true;}
 public void Placement(int slot,int block,string actor,int receipt,float now,bool paused){if(paused||phase!=GatewayPhase.Active||slot!=0||block<0||block>=ConstructionSite.YardPieces||receipt<=placementCursor||now<began||!PlaceContributionLog.ActorValid(actor))return;placementCursor=receipt;long bit=1L<<block;playerPieces&=~bit;creaturePieces&=~bit;if(actor=="player")playerPieces|=bit;else if(actor=="creature")creaturePieces|=bit;}
 public void Retain(long attached){if(phase!=GatewayPhase.Active)return;playerPieces&=attached;creaturePieces&=attached;}
 public bool Confirm(bool hitPlayer,bool hitCreature,float now,bool safe,bool paused){if(paused||!safe||phase!=GatewayPhase.Active||!HybridState.Number(now,began,100000000)||shots>=1000000)return false;shots++;playerHit|=hitPlayer;creatureHit|=hitCreature;if(playerHit&&creatureHit){phase=GatewayPhase.Complete;completed=Math.Min(1000000,completed+1);finished=now;}return true;}
 public bool Valid()=>Enum.IsDefined(typeof(GatewayPhase),phase)&&attempts>=0&&attempts<=1000000&&completed>=0&&completed<=attempts&&placementCursor>=0&&placementCursor<1000000000&&shots>=0&&shots<=1000000&&creatureShots>=0&&creatureShots<=returns&&creatureHits>=0&&creatureHits<=creatureShots&&lastCreatureTurn>=0&&lastCreatureTurn<=lastReturnedShot&&(creatureShots==0)==(lastCreatureTurn==0)&&returns>=0&&returns<=lastReturnedShot&&lastReturnedShot<=shots&&(returns==0)==(lastReturnedShot==0)&&HybridState.Number(began,0,100000000)&&HybridState.Number(finished,0,100000000)&&playerPieces>=0&&playerPieces<=Mask&&creaturePieces>=0&&creaturePieces<=Mask&&(playerPieces&creaturePieces)==0&&(!(playerHit||creatureHit)||shots>0)&&(phase==GatewayPhase.NotStarted?attempts==0&&completed==0&&shots==0&&playerPieces==0&&creaturePieces==0&&began==0&&finished==0:attempts>0)&&(phase!=GatewayPhase.Complete||playerHit&&creatureHit&&completed>0&&finished>=began)&&(phase==GatewayPhase.Complete||finished==0);
}
public static class BuildBowlText {
 public static CreationBookPage Read(SliceState s,int page){var p=s.buildBowl;page=Mathf.Clamp(page,2,3);if(page==3)return new CreationBookPage("Make it, then break it","Use the main yard's reusable blocks.\nPlace a piece while the creature watches.\nTap your block to renew its invitation.\n\nBuild a shared course. Take a shot.\nTopple one piece from each builder.\nLeave the ball for 12 seconds.\n\nIt may return the ball. Rebuild in view.\nThe creature can roll at the new piece.\nNo chores. Your hits stay separate.",3,4);
  string Done(bool b)=>b?"Done":"Open";string state=p?.phase==GatewayPhase.Complete?"A shared build, a successful knockdown.":p?.phase==GatewayPhase.Active?"Build together. Take turns at the course.":p?.phase==GatewayPhase.Ended?"Challenge ended. Your layout remains.":"Turn a shared construction into a toy course.";return new CreationBookPage("Build & Bowl",state+"\n\n"+Done(p?.playerPieces>0)+" · Your snapped pieces\n"+Done(p?.creaturePieces>0)+" · Creature's snapped pieces\n"+Done(p?.playerHit==true)+" · Your piece toppled safely\n"+Done(p?.creatureHit==true)+" · Creature's piece toppled safely\n\nSafe shots: "+(p?.shots??0)+" · Returns: "+(p?.returns??0)+"\nCreature hits: "+(p?.creatureHits??0)+" / "+(p?.creatureShots??0)+" · Completed: "+(p?.completed??0)+"\nFresh work after Begin counts.",2,4);}
}
public sealed partial class ConstructionSite {
 internal BeachBall buildBowlBall;public bool BuildBowlReserved=>buildBowlBall!=null&&(buildBowlBall.BuildBowlPending||buildBowlBall.BowlCreaturePending);
 public void RefreshBuildBowlEvidence(SliceState s){if(s.paused||s.buildBowl?.phase!=GatewayPhase.Active||contributionSlot!=0)return;long attached=0;for(int i=0;i<blocks.Count;i++)if(blocks[i].Attached&&!blocks[i].Item.held)attached|=1L<<i;s.buildBowl.Retain(attached);}
}
public sealed partial class QuestSlice {
 bool BuildBowlPage=>bookSection==CreationBookSection.Projects&&bookPage>=2;
 bool SelectedProjectActive=>BuildBowlPage?state.buildBowl?.phase==GatewayPhase.Active:state.gatewayProject?.phase==GatewayPhase.Active;
 bool SelectedProjectComplete=>BuildBowlPage?state.buildBowl?.phase==GatewayPhase.Complete:state.gatewayProject?.phase==GatewayPhase.Complete;
 void UseBookProject(){if(BuildBowlPage){if(SelectedProjectActive)MarkBuildBowl();else BeginBuildBowl();}else if(SelectedProjectActive)MarkGatewayProject();else BeginGatewayProject();}
 void EndBookProject(){if(BuildBowlPage)EndBuildBowl();else EndGatewayProject();}
 public bool BeginBuildBowl(){if(state.gatewayProject?.phase==GatewayPhase.Active){notice="End the gateway project before beginning Build & Bowl.";return false;}if(state.paused||applicationSuspended||held.Any(i=>i!=null)||state.gatewayProject?.phase==GatewayPhase.Active||state.buildBowl?.phase==GatewayPhase.Active)return false;var site=learning.sites[0];if(site.Paused||site.Locked||site.Repairer!=null||site.Requester!=null||site.Visitor!=null||curiosity.UsingConstruction(site)||site.blocks.Any(b=>b.Item.held||b.VillagerOwner!=null)){notice="Wait for the construction yard to be free.";return false;}var p=state.buildBowl??(state.buildBowl=new BuildBowlProject());if(!p.Begin(state.placeContributions?.nextId??1,state.Hybrid.time))return false;notice="Build & Bowl begun. Build together, then take your shot.";return true;}
 public bool EndBuildBowl(){if(state.paused||applicationSuspended||state.buildBowl?.End()!=true)return false;foreach(var ball in balls){ball.CancelCourseShot();ball.CancelBuildBowlReturn();}ClearOutingMark();notice="Challenge ended. Your layout remains.";return true;}
 public bool MarkBuildBowl(){if(state.paused||applicationSuspended||held.Any(i=>i!=null)||state.buildBowl?.phase!=GatewayPhase.Active)return false;return ShowActivityBeacon(learning.sites[0].transform);}
}
}
